<?php
try{$publicPerson=$publicStore->person((int)$recipient['contact_id']);if(!hash_equals($recipient['email_hash'],audienceDispatchEmailHash($publicPerson['email']))||$publicPerson['is_archived'])throw new InvalidArgumentException('This link no longer matches an active connection.');}catch(InvalidArgumentException){echo '<h1>Preferences unavailable</h1><p>Use the link in your most recent email.</p>';return;}
startSecureSession();$publicFields=array_filter($publicStore->fields(),static fn($f)=>!empty($f['is_public']));$publicGroups=array_filter($publicStore->groups(),static fn($g)=>$g['display_type']!=='hidden');
?>
<section class="subscription-panel"><h1>Update your preferences</h1><p>Choose the information and interests you share with this audience.</p>
<?php if($preferenceMessage): ?><p class="audience-notice" role="status"><?= $h($preferenceMessage) ?></p><?php endif; ?><?php if($preferenceError): ?><p class="audience-notice error" role="alert"><?= $h($preferenceError) ?></p><?php endif; ?>
<form method="post" class="subscription-form"><?= csrfInput() ?><input type="hidden" name="preference_action" value="save"><input type="hidden" name="version" value="<?= $publicPerson['version'] ?>">
<label>Email address<input type="email" readonly value="<?= $h($publicPerson['email']) ?>"></label><label>First name<input name="first_name" maxlength="100" value="<?= $h($publicPerson['first_name']) ?>"></label><label>Last name<input name="last_name" maxlength="100" value="<?= $h($publicPerson['last_name']) ?>"></label>
<?php foreach($publicFields as$f): $value=$publicPerson['custom'][$f['id']]??$f['default_value'];$options=audienceJson($f['options_json']);$name='custom['.$f['id'].']'; ?>
<?php if(in_array($f['field_type'],['radio','checkboxes'],true)): ?><fieldset><legend><?= $h($f['label']) ?></legend><?php foreach($options as$o): ?><label class="audience-check"><input type="<?= $f['field_type']==='checkboxes'?'checkbox':'radio' ?>" name="<?= $h($name.($f['field_type']==='checkboxes'?'[]':'')) ?>" value="<?= $h($o) ?>"<?= in_array($o,(array)$value,true)?' checked':'' ?>><?= $h($o) ?></label><?php endforeach; ?></fieldset>
<?php elseif($f['field_type']==='dropdown'): ?><label><?= $h($f['label']) ?><select name="<?= $h($name) ?>"><option value="">Choose an option</option><?php foreach($options as$o): ?><option<?= $value===$o?' selected':'' ?>><?= $h($o) ?></option><?php endforeach; ?></select></label>
<?php elseif($f['field_type']==='address'): ?><label><?= $h($f['label']) ?><textarea name="<?= $h($name) ?>" rows="5"><?= $h($value) ?></textarea></label>
<?php else: ?><label><?= $h($f['label']) ?><input name="<?= $h($name) ?>" maxlength="2000" type="<?= match($f['field_type']){'date'=>'date','number'=>'number',default=>'text'} ?>" value="<?= $h($value) ?>"<?= $f['required']?' required':'' ?>></label><?php endif; ?>
<?php endforeach; ?>
<?php foreach($publicGroups as$g): ?><fieldset><legend><?= $h($g['name']) ?></legend><?php if($g['display_type']==='dropdown'): ?><select name="group_pick[<?= $g['id'] ?>]"><option value="">Choose an interest</option><?php foreach($g['options']as$o): ?><option value="<?= $o['id'] ?>"<?= in_array((int)$o['id'],$publicPerson['group_ids'],true)?' selected':'' ?>><?= $h($o['name']) ?></option><?php endforeach; ?></select><?php else: ?><?php foreach($g['options']as$o): ?><label class="audience-check"><input type="<?= $g['display_type']==='radio'?'radio':'checkbox' ?>" name="<?= $g['display_type']==='radio'?'group_pick['.$g['id'].']':'group_ids[]' ?>" value="<?= $o['id'] ?>"<?= in_array((int)$o['id'],$publicPerson['group_ids'],true)?' checked':'' ?>><?= $h($o['name']) ?></label><?php endforeach; ?><?php endif; ?></fieldset><?php endforeach; ?>
<label>Time zone<select name="timezone"><option value="">Not set</option><?php foreach(DateTimeZone::listIdentifiers()as$zone): ?><option<?= $publicPerson['timezone']===$zone?' selected':'' ?>><?= $h($zone) ?></option><?php endforeach; ?></select></label><button class="primary">Update profile</button></form>
<hr><h2>Email subscription</h2><p><?= $h(ucfirst($publicPerson['email_status'])) ?></p><?php if(in_array($publicPerson['email_status'],['unsubscribed','non-subscribed','pending'],true)): ?><form method="post"><?= csrfInput() ?><input type="hidden" name="preference_action" value="confirm"><button>Send subscription confirmation</button></form><p class="audience-help">We will email a single-use confirmation to this address. Updating your profile never subscribes you automatically.</p><?php endif; ?><a href="?token=<?= $h($token) ?>">Unsubscribe from this audience</a></section>
